<?php
namespace App\Filament\Resources\CurriculumTemplates;
use App\Models\CurriculumTemplate; use App\Filament\Resources\CurriculumTemplates\Pages; use Filament\Forms\Components\{Select,TextInput}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\{Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table}; use BackedEnum; use UnitEnum;
class CurriculumTemplateResource extends Resource { protected static ?string $slug = 'curriculum-templates'; protected static ?string $model=CurriculumTemplate::class; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedDocumentDuplicate; protected static string|UnitEnum|null $navigationGroup='Kurikulum & Mata Kuliah'; protected static ?string $navigationLabel='Template Kurikulum'; protected static ?string $modelLabel='Template Kurikulum'; protected static ?string $pluralModelLabel='Template Kurikulum'; public static function form(Schema $schema):Schema{return $schema->components([Select::make('curriculum_id')->label('Kurikulum')->relationship('curriculum','name')->searchable()->preload()->required(),TextInput::make('entry_year')->label('Tahun Masuk')->numeric()->minValue(1900)->maxValue((int)date('Y')+5)->required(),TextInput::make('max_sks_per_semester')->label('Maksimal SKS per Semester')->numeric()->minValue(1)->maxValue(40)->default(24)->required(),TextInput::make('min_sks_per_semester')->label('Minimal SKS per Semester')->numeric()->minValue(0)->maxValue(40)->default(12)->required()->lte('max_sks_per_semester'),TextInput::make('total_credits_required')->label('Total SKS Kelulusan')->numeric()->minValue(1)->maxValue(300)->required()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('curriculum.name')->label('Kurikulum')->searchable(),TextColumn::make('entry_year')->label('Tahun Masuk'),TextColumn::make('min_sks_per_semester')->label('Minimal SKS'),TextColumn::make('max_sks_per_semester')->label('Maksimal SKS'),TextColumn::make('total_credits_required')->label('Total SKS Kelulusan')])->actions([EditAction::make()->label('Ubah'),DeleteAction::make()->label('Hapus')->requiresConfirmation()]);} public static function getPages():array{return ['index'=>Pages\ListCurriculumTemplates::route('/'),'create'=>Pages\CreateCurriculumTemplate::route('/create'),'edit'=>Pages\EditCurriculumTemplate::route('/{record}/edit')];}}
